*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF21000.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate_2.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDate_2.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    edt_SDate_3.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDate_3.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep_2.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep_2.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp_2.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp_2.Reset();
    dts_dep_3.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep_3.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp_3.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp_3.Reset();
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do";
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral&outputMessageId=LISTED_SEARCH_ADMISU_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.curr.admisu.select.condition" + "&{P}param01=" + "&{P}param02=";
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral&outputMessageId=LISTED_SEARCH_ADMISU_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.history.admisu.select.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD_2) + "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD_2) + "&{P}param03=" + $c.stf.getObjectValue(txb_ADMISU_DESIGN_RSN_CD) + "&{P}param04=" + $c.stf.getObjectValue(txb_ADMISU_DESIGN_RSN_CD) + "&{P}param05=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD_2) + "&{P}param06=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD_2) + "&{P}param07=" + $c.stf.getObjectValue(edt_SDate_2) + "&{P}param08=" + $c.stf.getObjectValue(edt_EDate_2) + "&{P}param09=" + $c.stf.getObjectValue(cmb_TeamList_2) + "&{P}param10=" + $c.stf.getObjectValue(cmb_TeamList_2) + "&{P}param11=" + $c.stf.getObjectValue(cmb_EmpList_2) + "&{P}param12=" + $c.stf.getObjectValue(cmb_EmpList_2) + "&{P}param13=" + $c.stf.getObjectValue(cmb_ADMISU_DESIGN_BZ_TP_CD) + "&{P}param14=" + $c.stf.getObjectValue(cmb_ADMISU_DESIGN_BZ_TP_CD);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral&outputMessageId=LISTED_SEARCH_ADMISU_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.bfaf.admisu.select.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD_3) + "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD_3) + "&{P}param03=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD_3) + "&{P}param04=" + $c.stf.getObjectValue(rdo_LIST_STAT_CD_3) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate_3) + "&{P}param06=" + $c.stf.getObjectValue(edt_EDate_3) + "&{P}param07=" + $c.stf.getObjectValue(cmb_TeamList_3) + "&{P}param08=" + $c.stf.getObjectValue(cmb_TeamList_3) + "&{P}param09=" + $c.stf.getObjectValue(cmb_EmpList_3) + "&{P}param10=" + $c.stf.getObjectValue(cmb_EmpList_3);
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.Reset();
        $c.cm.ShowWin(grd_List_3);
    }
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "1";
    arrPar[1] = "07";
    arrPar[2] = txb_ADMISU_DESIGN_RSN_CD; // 코드값을 포함할 컨트롤
    arrPar[3] = txb_ADMISU_DESIGN_RSN_NM; // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    txb_ADMISU_DESIGN_RSN_CD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_ADMISU_DESIGN_RSN_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};
scwin.img_ADMISU_DESIGN_RSN_CD_onclick = function() {
    $c.lc.fn_PopFindClssLstRsnCd();
};
scwin.img_COM_NM_2_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD_2, txb_COM_NM_2);
};
scwin.img_COM_NM_3_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD_3, txb_COM_NM_3);
};
scwin.btn_Search_2_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate_2, edt_EDate_2)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Search_3_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate_3, edt_EDate_3)) {
        scwin.fn_list_sync();
    }
};
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    var Rows;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        Rows = dts_List_1.getTotalRow();
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        Rows = dts_List_2.getTotalRow();
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        Rows = dts_List_3.getTotalRow();
    }
    $c.stf.FillGridHeaderTotalCnt(Rows, panel_page);
    //fn_list_sync();

};
scwin.btn_SDate_2_onclick = function() {
    popUpCalendar2(edt_SDate_2);
};
scwin.btn_EDate_2_onclick = function() {
    popUpCalendar2(edt_EDate_2);
};
scwin.btn_SDate_3_onclick = function() {
    popUpCalendar2(edt_SDate_3);
};
scwin.btn_EDate_3_onclick = function() {
    popUpCalendar2(edt_EDate_3);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "현재 관리종목", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "관리종목지정내역", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.data.downloadGridViewExcel(grd_List_3, "관리종목지정일자별 전후현황", "", "8");
    }
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_List_3_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_3); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_3_OnLoadError = function() {
    $c.stf.alert_error(dts_List_3);
};
scwin.dts_emp_2_OnLoadError = function() {
    $c.stf.alert_error(dts_emp_2);
};
scwin.dts_emp_3_OnLoadError = function() {
    $c.stf.alert_error(dts_emp_3);
};
scwin.dts_dep_2_OnLoadError = function() {
    $c.stf.alert_error(dts_dep_2);
};
scwin.dts_dep_3_OnLoadError = function() {
    $c.stf.alert_error(dts_dep_3);
};
scwin.cmb_TeamList_2_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList_2, "VALUE", cmb_TeamList_2.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_TeamList_2, '');
    }
    dts_emp_2.UseFilter = true;
    dts_emp_2.Filter();
    dts_emp_2.sort("DEP_CD", 0);
    //dts_emp_2.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_2_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp_2.getCellData(row, "dep_cd") == scwin.gDepCd || dts_emp_2.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_TeamList_3_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList_3, "VALUE", cmb_TeamList_3.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_TeamList_3, '');
    }
    dts_emp_3.UseFilter = true;
    dts_emp_3.Filter();
    dts_emp_3.sort("DEP_CD", 0);
    //dts_emp_3.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_3_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp_3.getCellData(row, "dep_cd") == scwin.gDepCd || dts_emp_3.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_PeriodTp_2_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp_2, "VALUE", cmb_PeriodTp_2.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate_2, edt_EDate_2);
};
scwin.cmb_PeriodTp_3_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp_3, "VALUE", cmb_PeriodTp_3.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate_3, edt_EDate_3);
};
scwin.txb_ISUR_CD_2_onblur = function() {
    if (txb_ISUR_CD_2.getValue() == "") {
        txb_COM_NM_2.setValue("");
    }
};
scwin.txb_ISUR_CD_3_onblur = function() {
    if (txb_ISUR_CD_3.getValue() == "") {
        txb_COM_NM_3.setValue("");
    }
};
scwin.txb_ADMISU_DESIGN_RSN_CD_onblur = function() {
    if (txb_ADMISU_DESIGN_RSN_CD.getValue() == "") {
        txb_ADMISU_DESIGN_RSN_NM.setValue("");
    }
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top_2);
    $c.cm.PanelToGroupBox(panel_Top_3);
    MaxTab_01.setSelectedTabIndex(1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_2);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_3);

    /*
    	fn_com_isur(txb_ISUR_CD_2, txb_COM_NM_2);
    	fn_com_isur(txb_ISUR_CD_3, txb_COM_NM_3);

    	Grd_com_isur_2.style.zIndex = 30;
    	Grd_com_isur_3.style.zIndex = 30;
    */

    $c.stf.showObj(Grd_com_isur_2, false);
    $c.stf.showObj(Grd_com_isur_3, false);
    scwin.fn_SetCode();
    scwin.fn_list_sync();
};
